/**
 * LDmicro library for Renesas RA4M1 (Arduino Nano R4), written on the CMSIS device header.
 * Distributed under the same license as LDmicro (GPL v3 or later).
 */
/*
 * SystemInit() is called by the code generated by LDmicro (mainPlc()).
 *
 * The program is started by the DFU bootloader of the Arduino Nano R4 and is
 * linked at 0x4000: the vector table is moved there. The option-setting
 * memory (OFS1: HOCO = 48 MHz) belongs to the bootloader and is not touched.
 *
 * Clocks (same as the Arduino core): HOCO 48 MHz as system clock,
 * ICLK = PCLKA = PCLKC = PCLKD = 48 MHz, PCLKB = FCLK = 24 MHz.
 */
#include "Lib_mcu.h"

#define LIB_CLOCK_TIMEOUT 400000U

extern uint32_t __isr_vector; /* start of the vector table (startup file) */

uint32_t SystemCoreClock = 8000000U; /* MOCO after a hardware reset */

static void LibSys_PinOutput(uint32_t port, uint32_t pin, uint32_t level, uint32_t drive)
{
    /* PODR (bit 0), PDR (bit 2), DSCR (bits 10 and 11) */
    R_PFS->PORT[port].PIN[pin].PmnPFS = (level & 1U) | 0x04U | (drive << 10);
}

void SystemInit(void)
{
    uint32_t n;

    /* The bootloader may leave interrupt lines linked to its own events (USB): release them all */
    for(n = 0; n < 32; n++) {
        NVIC_DisableIRQ((IRQn_Type)n);
        R_ICU->IELSR[n] = 0;
        NVIC_ClearPendingIRQ((IRQn_Type)n);
    }

    /* Vector table of this program */
    SCB->VTOR = (uint32_t)&__isr_vector;

    /* FPU: full access to CP10 and CP11 */
    SCB->CPACR |= ((3UL << (10 * 2)) | (3UL << (11 * 2)));

    /* Cycle counter, used by delay_us() and delay_ms() */
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
    DWT->CYCCNT = 0;
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;

    /* This program does not use the USB port: detach it if the bootloader left it attached
       (MSTPB11 = 0 means that the USB module is running) */
    if((R_MSTP->MSTPCRB & (1UL << 11)) == 0) {
        R_USB_FS0->SYSCFG_b.DPRPU = 0;
        R_USB_FS0->SYSCFG_b.USBE = 0;
    }

    R_SYSTEM->PRCR = LIB_PRCR_UNLOCK;

    /* HOCO on (48 MHz, selected by OFS1) */
    R_SYSTEM->HOCOCR = 0;
    for(n = 0; (R_SYSTEM->OSCSF_b.HOCOSF == 0) && (n < LIB_CLOCK_TIMEOUT); n++)
        ;

    if(R_SYSTEM->OSCSF_b.HOCOSF) {
        /* High-speed operating power control mode (the RA4M1 starts in middle-speed mode) */
        for(n = 0; R_SYSTEM->OPCCR_b.OPCMTSF && (n < LIB_CLOCK_TIMEOUT); n++)
            ;
        R_SYSTEM->OPCCR = 0;
        for(n = 0; R_SYSTEM->OPCCR_b.OPCMTSF && (n < LIB_CLOCK_TIMEOUT); n++)
            ;

        /* One wait cycle for the flash memory above 32 MHz */
        R_SYSTEM->MEMWAIT = 1;

        /* FCLK /2, ICLK /1, PCLKA /1, PCLKB /2, PCLKC /1, PCLKD /1, then HOCO as system clock */
        R_SYSTEM->SCKDIVCR = (1UL << 28) | (0UL << 24) | (0UL << 12) | (1UL << 8) | (0UL << 4) | 0UL;
        R_SYSTEM->SCKSCR = 0;
        SystemCoreClock = 48000000U;
    } else {
        SystemCoreClockUpdate();
    }

    R_SYSTEM->PRCR = LIB_PRCR_LOCK;

    /* Writing to the pin function registers (PmnPFS) stays enabled for the libraries */
    R_PMISC->PWPR = 0;
    R_PMISC->PWPR = 0x40;

    /* Board signals, driven as the Arduino core does for the Nano R4 */
    LibSys_PinOutput(0, 11, 0, 0);
    LibSys_PinOutput(0, 12, 1, 1);
    LibSys_PinOutput(0, 13, 0, 0);
    LibSys_PinOutput(2, 1, 1, 0);
}

void SystemCoreClockUpdate(void)
{
    static const uint32_t source[8] = {48000000U, 8000000U, 32768U, 0U, 32768U, 0U, 0U, 0U}; /* HOCO, MOCO, LOCO, main, sub, PLL */
    uint32_t              hz = source[R_SYSTEM->SCKSCR & 7U];

    if(hz == 0)
        hz = 8000000U;
    SystemCoreClock = hz >> ((R_SYSTEM->SCKDIVCR >> 24) & 7U);
}
